import json

from openvino.runtime import Model, PartialShape       # pylint: disable=no-name-in-module,import-error
from openvino.runtime.utils.types import get_dtype      # pylint: disable=no-name-in-module,import-error


def json_model_analysis_dump(framework_model: Model):

    def dump_partial_shape(shape: PartialShape):
        if shape.rank.is_dynamic:
            return 'None'
        dims = []
        for i in range(shape.rank.get_length()):
            dim = shape.get_dimension(i)
            dims.append(dim.get_length() if dim.is_static else 0)
        return dims

    def dump_element_type(ov_type):
        try:
            return str(get_dtype(ov_type))
        except:  # pylint: disable=bare-except
            return 'None'

    json_dump = {}
    json_dump['inputs'] = {}
    for param in framework_model.get_parameters():
        param_name = param.friendly_name
        json_dump['inputs'][param_name] = {
            'shape': dump_partial_shape(param.get_output_partial_shape(0)),
            'data_type': dump_element_type(param.get_output_element_type(0)),
            'value': 'None',  # any value is not available for analysis
        }

    json_dump['intermediate'] = {}
    for op in framework_model.get_ordered_ops():
        for out in op.outputs():
            for name in out.get_names():
                json_dump['intermediate'][name] = {
                    'shape': dump_partial_shape(out.get_partial_shape()),
                    'data_type': dump_element_type(out.get_element_type()),
                    'value': 'None',  # any value is not available for analysis
                }

    json_model_analysis_print(json_dump)


def json_model_analysis_print(json_dump: dict):
    print(json.dumps(json_dump))
